import pytestfrom app.main import get_human_age@pytest.mark.parametrize(    "cat_age, dog_age, expected",    [        (0, 0, [0, 0]),        (14, 14, [0, 0]),        (15, 15, [1, 1]),        (23, 23, [1, 1]),        (24, 24, [2, 2]),        (28, 28, [3, 2]),        (100, 100, [21, 17]),    ],)def test_get_human_age(cat_age: int, dog_age: int, expected: list) -> None:    assert get_human_age(cat_age, dog_age) == expected@pytest.mark.parametrize(    "cat_age, dog_age, expected",    [        (14, 0, [0, 0]),        (15, 0, [1, 0]),        (23, 0, [1, 0]),        (24, 0, [2, 0]),        (27, 0, [2, 0]),        (28, 0, [3, 0]),        (0, 14, [0, 0]),        (0, 15, [0, 1]),        (0, 23, [0, 1]),        (0, 24, [0, 2]),        (0, 28, [0, 2]),        (0, 29, [0, 3]),    ],)def test_age_boundaries(cat_age: int, dog_age: int, expected: list) -> None:    assert get_human_age(cat_age, dog_age) == expected@pytest.mark.parametrize(    "cat_age, dog_age, expected",    [        (14, 15, [0, 1]),        (15, 14, [1, 0]),        (23, 24, [1, 2]),        (24, 23, [2, 1]),        (27, 29, [2, 3]),        (28, 27, [3, 2]),    ],)def test_age_boundaries_14_29(        cat_age: int,        dog_age: int,        expected: list) -> None:    assert get_human_age(cat_age, dog_age) == expected@pytest.mark.parametrize(    "cat_age, dog_age",    [        (-1, 10),        (10, -1),    ],)def test_negative_age(cat_age: int, dog_age: int) -> None:    with pytest.raises(ValueError):        get_human_age(cat_age, dog_age)@pytest.mark.parametrize(    "cat_age, dog_age",    [        ("15", 15),        (15, "15"),        (None, 15),        (15, None),    ],)def test_incorrect_type(cat_age: int, dog_age: int) -> None:    with pytest.raises(TypeError):        get_human_age(cat_age, dog_age)